import{_ as a,c as r,o as i,al as t}from"./chunks/framework.CT7RwC5a.js";const p=JSON.parse('{"title":"MAVLink Peripherals (GCS/OSD/Gimbal/Camera/Companion)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/peripherals/mavlink_peripherals.md","filePath":"uk/peripherals/mavlink_peripherals.md"}'),o={name:"uk/peripherals/mavlink_peripherals.md"};function n(l,e,s,c,m,d){return i(),r("div",null,e[0]||(e[0]=[t('<h1 id="mavlink-peripherals-gcs-osd-gimbal-camera-companion" tabindex="-1">MAVLink Peripherals (GCS/OSD/Gimbal/Camera/Companion) <a class="header-anchor" href="#mavlink-peripherals-gcs-osd-gimbal-camera-companion" aria-label="Permalink to &quot;MAVLink Peripherals (GCS/OSD/Gimbal/Camera/Companion)&quot;">​</a></h1><p>Ground Control Stations (GCS), On-Screen Displays (OSD), MAVLink Cameras &amp; Gimbals, Remote IDs, Companion Computers, ADS-B receivers, and other MAVLink peripherals interact with PX4 using separate MAVLink streams, sent via different serial ports.</p><p>In order to configure that a particular serial port is used for MAVLink traffic with a particular peripheral, we use <a href="./../peripherals/serial_configuration.html">Serial Port Configuration</a>, assigning one of the abstract &quot;MAVLink instance&quot; configuration parameters to the desired port. Потім ми встановлюємо інші властивості каналу MAVLink, використовуючи параметри, пов&#39;язані з обраним екземпляром MAVLink, щоб вони відповідали вимогам нашого конкретного периферійного пристрою.</p><p>The most relevant parameters are described below (the full set are listed in the <a href="./../advanced_config/parameter_reference.html#mavlink">Parameter Reference &gt; MAVLink</a>).</p><h2 id="екземпляри-mavlink" tabindex="-1">Екземпляри MAVLink <a class="header-anchor" href="#екземпляри-mavlink" aria-label="Permalink to &quot;Екземпляри MAVLink&quot;">​</a></h2><p>In order to assign a particular peripheral to a serial port we use the concept of a <em>MAVLink instance</em>.</p><p>Кожен екземпляр MAVLink представляє певну конфігурацію MAVLink, яку ви можете застосувати до певного порту. At time of writing three MAVLink <em>instances</em> are defined, each represented by a parameter <a href="#MAV_X_CONFIG">MAV_X_CONFIG</a>, where X is 0, 1, 2.</p><p>Each instance has associated parameters that you can use to define the properties of the instance on that port, such as the set of streamed messages (see <a href="#MAV_X_MODE">MAV_X_MODE</a> below), data rate (<a href="#MAV_X_RATE">MAV_X_RATE</a>), whether incoming traffic is forwarded to other MAVLink instances (<a href="#MAV_X_FORWARD">MAV_X_FORWARD</a>), and so on.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>MAVLink instances are an abstract concept for a particular MAVLink configuration. Число в назві нічого не означає; ви можете призначити будь-який екземпляр до будь-якого порту.</p></div><p>Параметри для кожного екземпляру є:</p><ul><li><p><a id="MAV_X_CONFIG"></a><a href="./../advanced_config/parameter_reference.html#MAV_0_CONFIG">MAV_X_CONFIG</a> - Set the serial port (UART) for this instance &quot;X&quot;, where X is 0, 1, 2. It can be any unused port, e.g.: <code>TELEM2</code>, <code>TELEM3</code>, <code>GPS2</code> etc. For more information see <a href="./../peripherals/serial_configuration.html">Serial Port Configuration</a>.</p></li><li><p><a id="MAV_X_MODE"></a><a href="./../advanced_config/parameter_reference.html#MAV_0_MODE">MAV_X_MODE</a> - Specify the telemetry mode/target (the set of messages to stream for the current instance and their rate). Значення за замовчуванням:</p><ul><li><em>Normal</em>: Standard set of messages for a GCS.</li><li><em>Custom</em> or <em>Magic</em>: Nothing (in the default PX4 implementation). Режими можуть бути використані для тестування при розробці нового режиму.</li><li><em>Onboard</em>: Standard set of messages for a companion computer.</li><li><em>OSD</em>: Standard set of messages for an OSD system.</li><li><em>Config</em>: Standard set of messages and rate configuration for a fast link (e.g. USB).</li><li><em>Minimal</em>: Minimal set of messages for use with a GCS connected on a high latency link.</li><li><em>External Vision</em>: Messages for offboard vision systems.</li><li><em>Gimbal</em>: Messages for a gimbal. Note this also enables <a href="#MAV_X_FORWARD">message forwarding</a></li><li><em>Onboard Low Bandwidth</em>: Standard set of messages for a companion computer connected on a lower speed link.</li><li><em>uAvionix</em>: Messages for a uAvionix ADS-B beacon.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you need to find the specific set of message for each mode search for <code>MAVLINK_MODE_</code> in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_main.cpp" target="_blank" rel="noreferrer">/src/modules/mavlink/mavlink_main.cpp</a>.</p></div></li></ul><p>:::</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The mode defines the <em>default</em> messages and rates. A connected MAVLink system can still request the streams/rates that it wants using <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_SET_MESSAGE_INTERVAL" target="_blank" rel="noreferrer">MAV_CMD_SET_MESSAGE_INTERVAL</a>.</p></div><ul><li><p><a id="MAV_X_RATE"></a><a href="./../advanced_config/parameter_reference.html#MAV_0_MODE">MAV_X_RATE</a> - Set the maximum <em>data rate</em> for this instance (bytes/second).</p><ul><li>Це комбінована ставка для всіх потоків окремого повідомлення (ставки для окремих повідомлень зменшуються, якщо загальна ставка перевищує це значення).</li><li>За замовчуванням налаштування, як правило, буде прийнятним, але може бути зменшено, якщо телеметричний зв&#39;язок стає насиченим і занадто багато повідомлень втрачається.</li><li>Значення 0 встановлює швидкість передачі даних вдвічі менше теоретичного значення.</li></ul></li><li><p><a id="MAV_X_FORWARD"></a><a href="./../advanced_config/parameter_reference.html#MAV_0_FORWARD">MAV_X_FORWARD</a> - Enable forwarding of MAVLink packets received by the current instance onto other interfaces. Це може бути використано, наприклад, для передачі повідомлень між GCS та супутнім комп&#39;ютером, щоб GCS міг спілкуватися з камерою, підключеною до супутнього комп&#39;ютера, яка підтримує MAVLink.</p></li></ul><p>Next you need to set the baud rate for the serial port you assigned above (in <code>MAV_X_CONFIG</code>).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You will need to reboot PX4 to make the parameter available (i.e. in QGroundControl).</p></div><p>The parameter used will depend on the <a href="./../advanced_config/parameter_reference.html#serial">assigned serial port</a> - for example: <code>SER_GPS1_BAUD</code>, <code>SER_TEL2_BAUD</code>, etc. Значення, яке ви використовуєте, буде залежати від типу підключення та можливостей підключеного периферійного пристрою MAVLink.</p><h2 id="default_ports" tabindex="-1">Default MAVLink Ports <a class="header-anchor" href="#default_ports" aria-label="Permalink to &quot;Default MAVLink Ports {#default_ports}&quot;">​</a></h2><h3 id="telem1" tabindex="-1">TELEM1 <a class="header-anchor" href="#telem1" aria-label="Permalink to &quot;TELEM1&quot;">​</a></h3><p>The <code>TELEM 1</code> port is almost always configured by default for the GCS telemetry stream (&quot;Normal&quot;).</p><p>To support this there is a <a href="./../peripherals/serial_configuration.html#default_port_mapping">default serial port mapping</a> of MAVLink instance 0 as shown below:</p><ul><li><a href="./../advanced_config/parameter_reference.html#MAV_0_CONFIG">MAV_0_CONFIG</a> = <code>TELEM 1</code></li><li><a href="./../advanced_config/parameter_reference.html#MAV_0_MODE">MAV_0_MODE</a> = <code>Normal</code></li><li><a href="./../advanced_config/parameter_reference.html#MAV_0_RATE">MAV_0_RATE</a>= <code>1200</code> Bytes/s</li><li><a href="./../advanced_config/parameter_reference.html#MAV_0_FORWARD">MAV_0_FORWARD</a> = <code>True</code></li><li><a href="./../advanced_config/parameter_reference.html#SER_TEL1_BAUD">SER_TEL1_BAUD</a> = <code>57600</code></li></ul><h3 id="telem2" tabindex="-1">TELEM2 <a class="header-anchor" href="#telem2" aria-label="Permalink to &quot;TELEM2&quot;">​</a></h3><p>The <code>TELEM 2</code> port usually configured by default for a companion computer telemetry stream (&quot;Onboard&quot;).</p><p>To support this there is a <a href="./../peripherals/serial_configuration.html#default_port_mapping">default serial port mapping</a> of MAVLink instance 0 as shown below:</p><ul><li><a href="./../advanced_config/parameter_reference.html#MAV_0_CONFIG">MAV_1_CONFIG</a> = <code>TELEM 2</code></li><li><a href="./../advanced_config/parameter_reference.html#MAV_0_MODE">MAV_1_MODE</a> = <code>Onboard</code></li><li><a href="./../advanced_config/parameter_reference.html#MAV_0_RATE">MAV_1_RATE</a>= <code>0</code> (Half maximum)</li><li><a href="./../advanced_config/parameter_reference.html#MAV_0_FORWARD">MAV_1_FORWARD</a> = <code>Disabled</code></li><li><a href="./../advanced_config/parameter_reference.html#SER_TEL2_BAUD">SER_TEL2_BAUD</a> = <code>921600</code></li></ul><h3 id="ethernet" tabindex="-1">ETHERNET <a class="header-anchor" href="#ethernet" aria-label="Permalink to &quot;ETHERNET&quot;">​</a></h3><p>Пристрої Pixhawk 5x (і пізніші), які мають порт Ethernet, за замовчуванням налаштовані на підключення до GCS:</p><p>On this hardware, there is a <a href="./../peripherals/serial_configuration.html#default_port_mapping">default serial port mapping</a> of MAVLink instance 2 as shown below:</p><ul><li><a href="./../advanced_config/parameter_reference.html#MAV_2_CONFIG">MAV_2_CONFIG</a> = <code>Ethernet</code> (1000)</li><li><a href="./../advanced_config/parameter_reference.html#MAV_2_BROADCAST">MAV_2_BROADCAST</a> = <code>1</code></li><li><a href="./../advanced_config/parameter_reference.html#MAV_2_MODE">MAV_2_MODE</a> = <code>0</code> (normal/GCS)</li><li><a href="./../advanced_config/parameter_reference.html#MAV_2_RADIO_CTL">MAV_2_RADIO_CTL</a> = <code>0</code></li><li><a href="./../advanced_config/parameter_reference.html#MAV_2_RATE">MAV_2_RATE</a> = <code>100000</code></li><li><a href="./../advanced_config/parameter_reference.html#MAV_2_REMOTE_PRT">MAV_2_REMOTE_PRT</a>= <code>14550</code> (GCS)</li><li><a href="./../advanced_config/parameter_reference.html#MAV_2_UDP_PRT">MAV_2_UDP_PRT</a> = <code>14550</code> (GCS)</li></ul><p>For more information see: <a href="./../advanced_config/ethernet_setup.html">PX4 Ethernet Setup</a></p><h2 id="налаштування-пристрою" tabindex="-1">Налаштування пристрою <a class="header-anchor" href="#налаштування-пристрою" aria-label="Permalink to &quot;Налаштування пристрою&quot;">​</a></h2><p>Links to setup instructions for specific MAVLink components:</p><ul><li><a href="./../camera/mavlink_v2_camera.html#px4-configuration">MAVLink Cameras (Camera Protocol v2) &gt; PX4 Configuration</a></li><li><a href="./../advanced/gimbal_control.html#mavlink-gimbal-mnt-mode-out-mavlink">Gimbal Configuration &gt; MAVLink Gimbal (MNT_MODE_OUT=MAVLINK)</a></li></ul><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="./../peripherals/serial_configuration.html">Serial Port Configuration</a></li><li><a href="./../advanced_config/ethernet_setup.html#px4-mavlink-serial-port-configuration">PX4 Ethernet Setup &gt; PX4 MAVLink Serial Port Configuration</a></li><li><a href="./../hardware/serial_port_mapping.html">Serial Port Mapping</a></li></ul>',36)]))}const h=a(o,[["render",n]]);export{p as __pageData,h as default};
